import{_ as e,o as r,c as d,a0 as a}from"./chunks/framework.ZoVXsKRZ.js";const b=JSON.parse('{"title":"四川麻将「血战到底」规则速成","description":"","frontmatter":{"lastUpdated":true},"headers":[],"relativePath":"skills/sichuan.md","filePath":"skills/sichuan.md","lastUpdated":1784794489000}'),l={name:"skills/sichuan.md"};function n(i,t,o,s,h,g){return r(),d("div",null,[...t[0]||(t[0]=[a('<h1 id="四川麻将「血战到底」规则速成" tabindex="-1">四川麻将「血战到底」规则速成 <a class="header-anchor" href="#四川麻将「血战到底」规则速成" aria-label="Permalink to &quot;四川麻将「血战到底」规则速成&quot;">​</a></h1><p>四川麻将是全国最火爆的地方麻将玩法之一，以&quot;血流成河&quot;&quot;血战到底&quot;著称。节奏快、刺激性高，深受年轻人喜爱。</p><h2 id="基本参数" tabindex="-1">基本参数 <a class="header-anchor" href="#基本参数" aria-label="Permalink to &quot;基本参数&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>说明</th></tr></thead><tbody><tr><td><strong>人数</strong></td><td>4 人</td></tr><tr><td><strong>牌数</strong></td><td>108 张（万、筒、条各 36 张，<strong>无风箭字牌</strong>）</td></tr><tr><td><strong>打法</strong></td><td>缺一门 — 必须打缺一种花色才能胡牌</td></tr><tr><td><strong>摸牌</strong></td><td>庄家 14 张，闲家 13 张</td></tr><tr><td><strong>特色</strong></td><td><strong>血战到底</strong> — 一人胡牌后其余三家继续打，直到只剩一家未胡或流局</td></tr></tbody></table><hr><h2 id="核心规则" tabindex="-1">核心规则 <a class="header-anchor" href="#核心规则" aria-label="Permalink to &quot;核心规则&quot;">​</a></h2><h3 id="_1-缺一门是门槛" tabindex="-1">1. 缺一门是门槛 <a class="header-anchor" href="#_1-缺一门是门槛" aria-label="Permalink to &quot;1. 缺一门是门槛&quot;">​</a></h3><p>川麻最核心的规则：<strong>手牌必须打缺一种花色，才有资格听牌和胡牌。</strong></p><ul><li>缺万 → 手中没有万子牌</li><li>缺筒 → 手中没有筒子牌</li><li>缺条 → 手中没有条子牌</li></ul><p>每局开始前，系统会自动为你选择缺哪一门（根据起手牌花色数量最少的那门）。</p><h3 id="_2-血战到底" tabindex="-1">2. 血战到底 <a class="header-anchor" href="#_2-血战到底" aria-label="Permalink to &quot;2. 血战到底&quot;">​</a></h3><p>这是川麻最大的特色：</p><ol><li>第一家胡牌后，游戏<strong>不停止</strong></li><li>胡牌者退出，剩下三人继续打</li><li>第二家胡牌后，剩下两人继续</li><li>直到只剩最后一人未胡，或牌墙摸完 → 本局结束</li></ol><p>所以即便你胡了，也可能输给胡得更大的人！</p><h3 id="_3-不可吃、可碰可杠" tabindex="-1">3. 不可吃、可碰可杠 <a class="header-anchor" href="#_3-不可吃、可碰可杠" aria-label="Permalink to &quot;3. 不可吃、可碰可杠&quot;">​</a></h3><ul><li>❌ <strong>不能吃牌</strong>（只有上家打的牌不能拿来凑顺子）</li><li>✅ 可以碰</li><li>✅ 可以杠（明杠、暗杠、补杠）</li></ul><hr><h2 id="胡牌牌型与倍数" tabindex="-1">胡牌牌型与倍数 <a class="header-anchor" href="#胡牌牌型与倍数" aria-label="Permalink to &quot;胡牌牌型与倍数&quot;">​</a></h2><table tabindex="0"><thead><tr><th>番型</th><th>说明</th><th style="text-align:center;">倍数</th><th style="text-align:center;">难度</th></tr></thead><tbody><tr><td>平胡</td><td>最基本的胡牌，缺一门即可</td><td style="text-align:center;">1 倍</td><td style="text-align:center;">⭐</td></tr><tr><td>对对胡</td><td>全部由刻子（碰碰）组成</td><td style="text-align:center;">2 倍</td><td style="text-align:center;">⭐⭐</td></tr><tr><td>清一色</td><td>全部同一种花色</td><td style="text-align:center;">4 倍</td><td style="text-align:center;">⭐⭐⭐</td></tr><tr><td>七对</td><td>7 个对子</td><td style="text-align:center;">4 倍</td><td style="text-align:center;">⭐⭐⭐</td></tr><tr><td>金钩钓</td><td>碰碰胡 + 只剩一张将牌</td><td style="text-align:center;">4 倍</td><td style="text-align:center;">⭐⭐⭐</td></tr><tr><td>龙七对</td><td>七对中含一个杠（四张相同）</td><td style="text-align:center;">8 倍</td><td style="text-align:center;">⭐⭐⭐⭐</td></tr><tr><td>清大对</td><td>清一色 + 对对胡</td><td style="text-align:center;">8 倍</td><td style="text-align:center;">⭐⭐⭐⭐</td></tr><tr><td>十八罗汉</td><td>四个杠 + 一对将</td><td style="text-align:center;">极罕</td><td style="text-align:center;">⭐⭐⭐⭐⭐</td></tr></tbody></table><h3 id="杠牌特殊计算" tabindex="-1">杠牌特殊计算 <a class="header-anchor" href="#杠牌特殊计算" aria-label="Permalink to &quot;杠牌特殊计算&quot;">​</a></h3><table tabindex="0"><thead><tr><th>杠类型</th><th>说明</th><th>收益</th></tr></thead><tbody><tr><td>暗杠</td><td>自己摸到四张相同，暗杠</td><td>每家给 2 倍</td></tr><tr><td>明杠（直杠）</td><td>别人打出，你手上有三张</td><td>点杠者给 2 倍</td></tr><tr><td>补杠（巴杠）</td><td>碰后再摸到一张，补杠</td><td>每家给 1 倍</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">杠牌有风险</p><ul><li><strong>抢杠胡</strong>：补杠时别人可以抢胡这张牌，赔了夫人又折兵</li><li><strong>点杠</strong>：别人碰后再摸到第四张算明杠，被杠者要包杠钱，所以牌局后期慎碰</li></ul></div><hr><h2 id="新手避坑指南" tabindex="-1">新手避坑指南 <a class="header-anchor" href="#新手避坑指南" aria-label="Permalink to &quot;新手避坑指南&quot;">​</a></h2><h3 id="✅-要做的" tabindex="-1">✅ 要做的 <a class="header-anchor" href="#✅-要做的" aria-label="Permalink to &quot;✅ 要做的&quot;">​</a></h3><ol><li><strong>优先打缺花色牌</strong> — 摸到哪门少就打哪门，快速缺一门才能听牌</li><li><strong>中期看番型</strong> — 鸡胡只能赢 1 倍，尽量往对对胡或清一色方向做</li><li><strong>记对手缺什么</strong> — 别人缺万子，万字牌就安全，可以放心打</li><li><strong>胡小不如做大</strong> — 反正血战到底，小胡先走不一定赚</li></ol><h3 id="❌-不要做的" tabindex="-1">❌ 不要做的 <a class="header-anchor" href="#❌-不要做的" aria-label="Permalink to &quot;❌ 不要做的&quot;">​</a></h3><ol><li><strong>不要乱碰</strong> — 每次碰都会曝露自己的牌型方向</li><li><strong>不要盲目杠</strong> — 会被抢杠，尤其是补杠</li><li><strong>不要憋三家</strong> — 手里抓着别人缺门的花色没啥用，早点打掉</li><li><strong>不要只做平胡</strong> — 别人做清一色比你多 4 倍，鸡胡赢了也亏</li></ol><hr><h2 id="各平台川麻对比" tabindex="-1">各平台川麻对比 <a class="header-anchor" href="#各平台川麻对比" aria-label="Permalink to &quot;各平台川麻对比&quot;">​</a></h2><table tabindex="0"><thead><tr><th>平台</th><th>特点</th><th style="text-align:center;">推荐指数</th></tr></thead><tbody><tr><td><strong>腾讯欢乐麻将·四川麻将</strong></td><td>最主流，玩家多，匹配快</td><td style="text-align:center;">⭐⭐⭐⭐⭐</td></tr><tr><td><strong>途游四川麻将</strong></td><td>3D 画面精美，特效丰富</td><td style="text-align:center;">⭐⭐⭐⭐</td></tr><tr><td><strong>JJ斗地主·麻将</strong></td><td>比赛多，有现金奖励</td><td style="text-align:center;">⭐⭐⭐⭐</td></tr><tr><td><strong>闲来麻将</strong></td><td>地方特色浓，熟人局多</td><td style="text-align:center;">⭐⭐⭐</td></tr></tbody></table><hr><p><em>川麻千变万化，各地规则细节可能略有不同，以当地约定为准。</em></p>',33)])])}const u=e(l,[["render",n]]);export{b as __pageData,u as default};
